    commonIssues: ["replace 残留", "go.sum 冲突", "私有模块认证失败", "v2 路径后缀错误", "间接依赖版本被抬高", "go.work 影响本地结果", "checksum mismatch", "模块路径声明不一致", "代理缓存或企业代理改写内容", "CI 缓存键覆盖范围过宽"],
    practiceAdvice: ["用 go mod init 建立模块边界", "用 go mod tidy 收敛依赖", "用 go list -m all 查看最终版本", "用 go mod why -m 定位依赖来源", "用 go mod download -x 排查下载链路", "发布前清理本地 replace 和 workspace 影响", "私有模块统一配置 GOPRIVATE 与凭据", "用 go version -m 审计线上二进制依赖"],
